INSERT INTO `langkah` (`resep_id`, `grup`, `urutan`, `instruksi`) VALUES
(1, 'cara memasak', 1, 'Marinasi ayam dengan jeruk nipis dan garam selama kurang lebih 20 menit, lalu cuci bersih. Sisihkan.'),
(1, 'cara memasak', 2, 'Panaskan minyak di atas wajan besar, lalu tumis bumbu halus hingga harum.'),
(1, 'cara memasak', 3, 'Tuang santan. Aduk lalu rebus hingga mendidih.'),
(1, 'cara memasak', 4, 'Masukkan ayam. Masak hingga matang dan bumbu meresap. Matikan kompor.'),
(1, 'cara memasak', 5, 'Panggang ayam di atas bara api atau dalam oven api atas di temperatur 200 derajat celcius, posisi loyang nomer 2 dari atas. Sambil oles dengan bumbu yang tersisa, panggang hingga bumbu sedikit terbakar. Balik ayam, lakukan hal yang sama.'),
(1, 'cara memasak', 6, 'Jika sudah agak terbakar kedua sisi, keluarkan dari oven. Sajikan dengan lalapan, sambel cobek, dan nasi hangat.'),
(2, 'cara memasak', 1, 'Bakso: Iris bawang putih dan bawang merah, lalu goreng hingga kecoklatan atau matang.'),
(2, 'cara memasak', 2, 'Masukkan daging ke dalam food processor, tambahkan 2 cube es batu, lalu haluskan daging hingga lumat.'),
(2, 'cara memasak', 3, 'Masukkan bawang putih dan bawang merah goreng, merica, kaldu, garam, baking powder, es batu lagi. Adonan diaduk lagi hingga bercampur rata.'),
(2, 'cara memasak', 4, 'Masukkan tepung tapioka, dan es batu bila perlu. Adonan diaduk lagi hingga merata.'),
(2, 'cara memasak', 5, 'Panaskan air dengan api kecil dan jangan sampai mendidih. Tunggu hingga cukup panas.'),
(2, 'cara memasak', 6, 'Bentuk adonan bakso bulat-bulat sesuai selera menggunakan tangan dan sendok, masukkan bakso ke dalam air yang cukup panas. Tunggu hingga bakso mengapung di atas permukaan air, baru diangkat.'),
(2, 'cara memasak', 7, 'Kuah kaldu tulang: Cuci bersih tulang atau ribs.'),
(2, 'cara memasak', 8, 'Rebus tulang hingga mendidih selama 10 menit, kemudian kecilkan api, biarkan hingga 1 jam atau lebih.'),
(2, 'cara memasak', 9, 'Iris bawang putih dan bawang merah, lalu goreng hingga kecoklatan atau matang. Kemudian blender hingga halus.'),
(2, 'cara memasak', 10, 'Jika rebusan tulang sudah mengeluarkan kaldunya, masukkan bawang putih dan bawang merah yang sudah diblender dan bumbu lainnya ke dalam kuah tersebut. Koreksi rasanya.'),
(2, 'cara memasak', 11, 'Masukkan bakso ke dalam kuah kaldu. Tunggu hingga cukup matang dan kaldu meresap ke dalam bakso.'),
(2, 'cara memasak', 12, 'Masukkan daun bawang dan tambahkan bawang merah goreng.'),
(2, 'cara memasak', 13, 'Sambal bawang: Rebus cabe rawit dan bawang putih hingga empuk. Angkat dan haluskan menggunakan blender atau diulek (tambahkan sedikit garam dan gula). Taruh di mangkok sambal.'),
(2, 'cara memasak', 14, 'Penataan: Masukkan tahu goreng dan mie ke dalam mangkok, lalu tambahkan bakso dan tuangkan kuahnya. Taburkan dengan daun bawang dan bawang goreng, serta sambal bawang.'),
(3, 'cara memasak', 1, 'Panaskan minyak secukupnya lalu tumis bahan yang dihaluskan sampai wangi. Setelah itu masukkan udang yang sudah dilumuri jeruk nipis tadi.'),
(3, 'cara memasak', 2, 'Setelah udang berubah warna masukkan air. Setelah mendidih masukkan kentang.'),
(3, 'cara memasak', 3, 'Setelah kentang lunak masukkan tahu.'),
(3, 'cara memasak', 4, 'Tambahkan juga serai, daun jeruk purut, daun salam, garam, dan penyedap rasa. Aduk-aduk dengan pelan agar tahu tidak hancur.'),
(3, 'cara memasak', 5, 'Setelah bumbu meresap dan harum, masukkan santan bubuk yang telah dicampurkan dengan sedikit air terlebih dahulu. Lanjutkan mengaduk.'),
(3, 'cara memasak', 6, 'Jika kuah dirasa sudah mengental, uji rasa. Bila sudah dirasa pas, angkat dan sajikan langsung dengan nasi panas.'),
(4, 'cara memasak', 1, 'Lumuri ayam menggunakan jeruk nipis, remas-remas dan biarkan selama sekitar 10 menit.'),
(4, 'cara memasak', 2, 'Haluskan bawang putih, kunyit, ketumbar dan lada, lalu tumis hingga harum.'),
(4, 'cara memasak', 3, 'Masukkan ayam dan aduk hingga berubah warna. Tambahkan garam dan santan/air. Masak hingga ayam empuk dan bumbu meresap, matikan api.'),
(4, 'cara memasak', 4, 'Pada panci terpisah, tumis bumbu kuah yang telah dihaluskan bersama daun jeruk hingga harum. Masukkan tomat dan beri garam secukupnya.'),
(4, 'cara memasak', 5, 'Tambahkan santan dan susu ke dalamnya. Masak sampai kuah mendidih sambil ditimba-timba agar santan tidak pecah. Cicipi, jika dirasa sudah pas, masukkan ayam yang telah ditumis tadi ke dalam panci kuah. Masak sekitar 5 menit, matikan api.'),
(4, 'cara memasak', 6, 'Penyajian: Dalam mangkok tata lontong/ketupat yang telah dipotong-potong, telur, tempe, dan tahu putih. Siram dengan kuah glabed panas dan beri potongan ayam. Taburi bawang goreng, beri air jeruk nipis secukupnya serta sambal sesuai selera.'),
(5, 'cara memasak', 1, 'Panaskan 1 sdm minyak goreng lalu tumis tuna menggunakan api sedang sampai kering.'),
(5, 'cara memasak', 2, 'Blender kasar bawang, cabe merah besar, cabe rawit dan sereh.'),
(5, 'cara memasak', 3, 'Panaskan 7 sdm minyak goreng menggunakan api sedang lalu masukkan bahan-bahan yang sudah di blender. Tumis sebentar.'),
(5, 'cara memasak', 4, 'Masukkan air, gula dan garam lalu kecilkan api, masak kurang lebih 20 menit atau sampai air menyusut.'),
(5, 'cara memasak', 5, 'Masukkan tuna, lalu tumis kembali selama 5 menit.'),
(5, 'cara memasak', 6, 'Sambal ini menghasilkan sekitar 300 gr siap santap.'),
(6, 'cara memasak', 1, 'Goreng bawang merah, bawang putih, cabe rawit, dan tomat sebentar sekitar 3 menit. Kemudian blender semua bahan bumbu halus hingga rata (sebaiknya tidak menggunakan air saat memblender, tapi minyak goreng secukupnya).'),
(6, 'cara memasak', 2, 'Panaskan wajan dengan 2-3 sendok makan minyak goreng. Setelah itu, tumis udang sampai matang sekitar 5 menit. Sisihkan.'),
(6, 'cara memasak', 3, 'Di wajan yang sama, tambahkan sesendok minyak goreng lagi, masukkan irisan bawang merah, dan tumis sebentar hingga layu.'),
(6, 'cara memasak', 4, 'Masukkan bumbu halus dan tumis sekitar 5-7 menit. Tambahkan 1/4 cup air. Masukkan bubuk jinten dan kari. Tumis terus sampai harum, sekitar 6 menit.'),
(6, 'cara memasak', 5, 'Masukkan mi yang sudah didinginkan. Aduk terus, lalu tambahkan kecap asin dan manis secukupnya. Tumis terus hingga semua bahan menyatu.'),
(6, 'cara memasak', 6, 'Masukkan tauge. Aduk terus. Tambahkan minyak wijen dan cuka. Aduk terus hingga semua bahan tercampur rata. Koreksi rasanya.'),
(6, 'cara memasak', 7, 'Masukkan udang, daun bawang, dan daun sop. Aduk hingga semuanya tercampur rata.'),
(6, 'cara memasak', 8, 'Mie Aceh Udang siap disajikan dengan irisan tomat, taburan bawang goreng, kerupuk udang, dan kacang tanah goreng.'),
(7, 'cara memasak', 1, 'Haluskan bawang putih, bawang merah, cabai rawit, dan minyak dengan blender kemudian tumis hingga wangi.'),
(7, 'cara memasak', 2, 'Masukkan daun salam dan daun jeruk, tumis hingga wangi dan matang.'),
(7, 'cara memasak', 3, 'Masukkan kecap ikan, seasoning sauce, saus tiram, saus tomat, saus sambal, daun bawang, dan bagian putih, aduk rata.'),
(7, 'cara memasak', 4, 'Tambahkan air, aduk rata lalu masukkan gula dan kaldu bubuk.'),
(7, 'cara memasak', 5, 'Masukkan kerang yang telah direbus.'),
(7, 'cara memasak', 6, 'Panaskan minyak, goreng cumi dan udang selama 30-60 detik, tiriskan.'),
(7, 'cara memasak', 7, 'Masukkan sisa daun bawang, cumi, dan udang yang telah digoreng, (brokoli boleh dicampur atau dipisah untuk hiasan) masak hingga mendidih kemudian matikan api.'),
(7, 'cara memasak', 8, 'Seafood saus padang siap disajikan dengan nasi sebagai pelengkap.'),
(8, 'cara memasak', 1, 'Toping dendeng basah balado. Potong daging setebal 1 cm.'),
(8, 'cara memasak', 2, 'Lumuri dengan bawang putih, merica, dan garam. Biarkan selama 15 menit.'),
(8, 'cara memasak', 3, 'Pindahkan ke wajan, beri air dan masak sampai air habis dan daging empuk, angkat dan tiriskan daging.'),
(8, 'cara memasak', 4, 'Goreng daging dengan minyak panas sebentar saja tidak perlu sampai kering, angkat dan tiriskan.'),
(8, 'cara memasak', 5, 'Tumis cabe dan bawang dengan minyak sisa menggoreng daging hingga layu.'),
(8, 'cara memasak', 6, 'Masukkan daging goreng ke dalam sambal, aduk rata.'),
(8, 'cara memasak', 7, 'Penyajian: Rebus pasta, angkat dan tiriskan kedalam wadah. Sajikan dendeng balado diatas pasta sebagai toping.'),
(9, 'cara memasak', 1, 'Rebus hati ayam 1x mendidih untuk menghilangkan bau amis, tiriskan dan potong sesuai selera kemudian goreng sebentar.'),
(9, 'cara memasak', 2, 'Goreng kentang setengah matang.'),
(9, 'cara memasak', 3, 'Panaskan minyak di atas wajan besar, lalu tumis bumbu halus hingga harum. Tambahkan daun jeruk.'),
(9, 'cara memasak', 4, 'Tuang santan, masak hingga mendidih.'),
(9, 'cara memasak', 5, 'Masukkan hati ayam dan kentang masak hingga air santan habis dan bumbu meresap. Matikan kompor.'),
(10, 'cara memasak', 1, 'Cuci bersih bahan daging dan potong sesuai selera.'),
(10, 'cara memasak', 2, 'Marinasi ayam/daging/hati ayam dengan bumbu tersebut selama 2 jam, taruh di dalam kulkas.'),
(10, 'cara memasak', 3, 'Kemudian rebus dengan 1/2 gelas air dengan api kecil. Atau jika ayam/daging/hati sudah berair maka tidak perlu ditambah air.'),
(10, 'cara memasak', 4, 'Rebus hingga bumbu meresap dan air habis. Dinginkan.'),
(11, 'cara memasak gudeg', 1, 'Haluskan bumbu (disarankan ditumbuk untuk rasa yang lebih mantap).'),
(11, 'cara memasak gudeg', 2, 'Letakkan bumbu rempah di dasar panci/kuali.'),
(11, 'cara memasak gudeg', 3, 'Berikan sedikit garam dan gula merah.'),
(11, 'cara memasak gudeg', 4, 'Lanjutkan masukkan bumbu halus.'),
(11, 'cara memasak gudeg', 5, 'Untuk mendapatkan warna gudeg yang merah gelap bisa ditambahkan 10 sachet black tea.'),
(11, 'cara memasak gudeg', 6, 'Masukkan nangka yang sudah direbus.'),
(11, 'cara memasak gudeg', 7, 'Tuang santan dan tambahkan air sampai nangka terendam.'),
(11, 'cara memasak gudeg', 8, 'Masak dengan api kecil atau dengan slow cooker minimal 4-5 jam.'),
(11, 'cara memasak gudeg', 9, 'Jangan lupa dibolak balik biar tidak gosong.'),
(11, 'cara memasak gudeg', 10, 'Dapat dikoreksi rasanya, sesuai dengan selera.'),
(11, 'sambal krecek - cara memasak', 1, 'Tumis bawang merah dan bawang putih sampai matang dan harum.'),
(11, 'sambal krecek - cara memasak', 2, 'Masukkan cabai halus, lalu tumis lagi hingga benar-benar matang (berubah warna).'),
(11, 'sambal krecek - cara memasak', 3, 'Tuangi 800 ml santan.'),
(11, 'sambal krecek - cara memasak', 4, 'Tunggu sampai mendidih kemudian masukkan kacang tholo, tempe.'),
(11, 'sambal krecek - cara memasak', 5, 'Beri garam, kaldu bubuk serta gula merah.'),
(11, 'sambal krecek - cara memasak', 6, 'Masak sampai bumbu meresap.'),
(11, 'sambal krecek - cara memasak', 7, 'Siap sajikan bersama gudeg.'),
(11, 'opor ayam - cara memasak', 1, 'Tumis bumbu halus hingga harum.'),
(11, 'opor ayam - cara memasak', 2, 'Masukkan bumbu rempah.'),
(11, 'opor ayam - cara memasak', 3, 'Tuangi santan.'),
(11, 'opor ayam - cara memasak', 4, 'Beri garam/kaldu bubuk dan gula merah secukupnya.'),
(11, 'opor ayam - cara memasak', 5, 'Masak sampai ayam empuk dan kuah mengental dengan api kecil.'),
(12, 'cara memasak', 1, 'Campurkan lada, garam dan garlic powder ke dalam tepung terigu. Aduk merata.'),
(12, 'cara memasak', 2, 'Gulirkan ikan ke dalam racikan tepung sampai terlapisi merata.'),
(12, 'cara memasak', 3, 'Panaskan minyak, lalu goreng ikan di atas api sedang sampai matang. Tiriskan dan sisihkan ikan goreng.'),
(12, 'cara memasak', 4, 'Potong tomat cherry menjadi 4 bagian.'),
(12, 'cara memasak', 5, 'Iris tipis bawang merah.'),
(12, 'cara memasak', 6, 'Siapkan mangkuk kecil tahan panas.'),
(12, 'cara memasak', 7, 'Masukkan potongan tomat dan bawang merah, perasan jeruk nipis, irisan daun jeruk, gula, lada dan garam ke dalam mangkuk tahan panas. Sisihkan.'),
(12, 'cara memasak', 8, 'Panaskan minyak sampai panas dan hampir berasap, kemudian segera tuangkan ke dalam mangkuk sambal dabu-dabu. Aduk dan koreksi rasa.'),
(12, 'cara memasak', 9, 'Sajikan ikan goreng di atas piring, tambahkan sambal dabu-dabu diatasnya.'),
(13, 'cara memasak', 1, 'Ayam dibersihkan, dicuci, dan dibelah dua.'),
(13, 'cara memasak', 2, 'Bawang merah, bawang putih, cabai merah, kemiri, jinten, dan ketumbar dihaluskan/diblender.'),
(13, 'cara memasak', 3, 'Panaskan wajan penggorengan dengan menggunakan empat sendok makan minyak goreng. Tumislah bumbu yang sudah dihaluskan sampai harum, dan masukkan serainya.'),
(13, 'cara memasak', 4, 'Masukkan ayamnya diaduk sebentar, kemudian masukkan santannya, yang berikutnya masukkan daun salam, lengkuas, gula jawa dan garam.'),
(13, 'cara memasak', 5, 'Masak sampai santan mendidih, dan tutuplah wajan penggorengan/diungkep sampai santan mulai mengental dan berkurang, serta bumbu-bumbunya meresap. Angkat. Sisa-sisa bumbu jangan dibuang.'),
(13, 'cara memasak', 6, 'Ayam dipanggang di dalam oven atau dibakar diatas grill/barbeque sambil dibolak-balik, sesekali diolesi dengan sisa-sisa bumbu tadi, sampai matangnya merata dan kecoklatan.'),
(13, 'cara memasak', 7, 'Angkat dan sajikan dengan sambal terasi serta lalapan.'),
(14, 'cara memasak', 1, 'Aduk semua bahan menjadi satu hingga rata, kecuali wortel/sosis.'),
(14, 'cara memasak', 2, 'Ambil satu lembar plastik wrap, letakkan diatasnya 1/3 bagian adonan, ratakan pipih.'),
(14, 'cara memasak', 3, 'Letakkan 1 batang wortel atau sosis dibagian tengah. Gulung menjadi seperti lontong. Lakukan pada semua adonan.'),
(14, 'cara memasak', 4, 'Tusuk-tusuk dibeberapa bagian gulungan dengan tusuk gigi.'),
(14, 'cara memasak', 5, 'Kukus selama 30 menit. Angkat, dinginkan.'),
(14, 'cara memasak', 6, 'Goreng. Potong-potong. Sajikan rolade dengan pelengkap saos, wortel, buncis rebus dan French fries.'),
(15, 'cara memasak', 1, 'Potong-potong iga lamb dengan menurut alur tulangnya.'),
(15, 'cara memasak', 2, 'Bumbu dihaluskan, iga lamb dimasukkan dan dicampurkan secara merata kedalam bumbu, dan diinapkan semalam atau kalau terlalu lama setengah hari juga bisa.'),
(15, 'cara memasak', 3, 'Kemudian dipanggang atau dibakar, sesuai selera.'),
(16, 'cara memasak', 1, 'Tumis bawang bombay hingga harum.'),
(16, 'cara memasak', 2, 'Masukkan oregano, daging kambing dan tomat diikuti susu cair masak hingga susu meresap.'),
(16, 'cara memasak', 3, 'Masukkan kocokan telur dan aduk cepat hingga telur tidak pecah, dan diamkan 1 menit hingga telur masak.'),
(16, 'cara memasak', 4, 'Angkat, sajikan dengan nasi hangat.'),
(17, 'cara memasak', 1, 'Panaskan minyak di wajan, campur bahan 1 dan aduk rata.'),
(17, 'cara memasak', 2, 'Cetak dengan tangan bulat-bulat sebesar bola pingpong dan dipipihkan.'),
(17, 'cara memasak', 3, 'Setelah minyak panas, ambil satu adonan, gulingkan ke putih telur (bahan 2).'),
(17, 'cara memasak', 4, 'Goreng sampai kuning kecoklatan.'),
(17, 'cara memasak', 5, 'Sajikan untuk 12-15 buah.'),
(18, 'cara memasak', 1, 'Bumbu halus di tumis sebentar agak harum, dimasukkan serai, daun salam, daun jeruk lalu santannya.'),
(18, 'cara memasak', 2, 'Masukkan tempe kukus, spring green, petai potong kasar, teri, tomat, cabai hijau potongan, daun bawang dan diaduk rata.'),
(18, 'cara memasak', 3, 'Masukkan telur kocok kemudian diaduk rata kembali.'),
(18, 'cara memasak', 4, 'Seluruh bahan dibungkus dengan daun pisang atau alumunium foil sesuai selera. Dapat dijadikan beberapa bungkus, lalu dikukus selama kurang lebih 30 sampai 45 menit.'),
(19, 'cara memasak', 1, 'Rebus curly kale/spring cabbage. Sisihkan.'),
(19, 'cara memasak', 2, 'Saus: goreng cabe + bawang merah, lalu haluskan cabe, terasi, dan bawang merah.'),
(19, 'cara memasak', 3, 'Panaskan sedikit minyak, tumis bumbu halus sampai harum. Tuangi air.'),
(19, 'cara memasak', 4, 'Masukkan asam, gula jawa dan garam. Aduk rata sampai mendidih dan agak kental. Matikan api.'),
(20, 'cara memasak', 1, 'Tumis bawang bombay, bawang putih, hingga harum.'),
(20, 'cara memasak', 2, 'Masukkan udang, tahu dan tambah air sedikit.'),
(20, 'cara memasak', 3, 'Tambahkan kecap, oyster sauce, garam dan merica.'),
(20, 'cara memasak', 4, 'Masukkan daun Mustard Green, aduk hingga rata.'),
(20, 'cara memasak', 5, 'Masak daun Kai Choi setengah matang. Angkat. Sajikan.'),
(21, 'cara memasak', 1, 'Ayam bungkus telor: Campur daging ayam cincang, telor dan bumbu halus, aduk rata.'),
(21, 'cara memasak', 2, 'Ambil selembar dadar, isi dengan 1 sendok makan adonan ayam, lipat seperti amplop/kantong. Lakukan sampai adonan habis.'),
(21, 'cara memasak', 3, 'Kukus selama sekitar 30 menit dan sisihkan.'),
(21, 'cara memasak', 4, 'Kuah sup: Tumis bawang bombay sampai layu.'),
(21, 'cara memasak', 5, 'Masukkan bawang putih dan lada putih, tumis sampai harum.'),
(21, 'cara memasak', 6, 'Tuangi dengan air kaldu ayam, masukkan garam + gula pasir secukupnya.'),
(21, 'cara memasak', 7, 'Rebus sampai mendidih.'),
(21, 'cara memasak', 8, 'Penyajian: Tata ayam bungkus telor, rebusan wortel + jamur putih + kacang polong + irisan daun bawang dan seledri dalam mangkuk/piring. Tuangi dengan kuah panas, sajikan.'),
(22, 'cara memasak', 1, 'Cuci iga kambing, rebus dalam air bersama jahe dan garam hingga berubah warna.'),
(22, 'cara memasak', 2, 'Panaskan minyak, tumis bumbu halus, kayu manis dan cengkeh. Aduk hingga harum dan angkat.'),
(22, 'cara memasak', 3, 'Masukkan ke dalam kaldu rebusan iga. Didihkan dan kecilkan apinya. Tutup panci dan masak hingga bumbu meresap dan daging empuk.'),
(22, 'cara memasak', 4, 'Masukkan wortel dan brokoli, setelah cukup layu.'),
(22, 'cara memasak', 5, 'Masukkan daun bawang dan tomat, dibiarkan cukup layu.'),
(22, 'cara memasak', 6, 'Angkat, sajikan hangat bersama taburan dan pelengkap.'),
(23, 'cara memasak', 1, 'Rebus ayam selama 10 menit, buang rebusan pertama.'),
(23, 'cara memasak', 2, 'Angkat ayam tambahkan 2 liter air dan rebus kembali.'),
(23, 'cara memasak', 3, 'Tumis bumbu halus sampai wangi.'),
(23, 'cara memasak', 4, 'Masukkan bumbu halus ke rebusan ayam.'),
(23, 'cara memasak', 5, 'Masukkan bumbu cemplung lanjut rebus sampai ayam lunak.'),
(23, 'cara memasak', 6, 'Suwir-suwir ayam jika sudah empuk.'),
(23, 'cara memasak', 7, 'Sajikan dengan lontong, telor rebus dan perkedel kentang.'),
(24, 'cara memasak', 1, 'Bersihkan ikan, lumuri dengan perasan jeruk nipis. Sisihkan.'),
(24, 'cara memasak', 2, 'Campur bumbu halus dengan lelehan butter, kecap manis, dan garam ke dalam wadah.'),
(24, 'cara memasak', 3, 'Masukkan ikan ke bumbu, campur hingga merata, kemudian marinate/diamkan sekitar 20 menit (lebih lama lebih baik).'),
(24, 'cara memasak', 4, 'Panaskan oven. Panggang ikan di oven dengan suhu 180 C selama 15 menit, kemudian keluarkan ikan. Olesi dengan sisa bumbu dan panggang kembali selama 15 menit/sampai tingkat kematangan yang diinginkan.'),
(24, 'cara memasak', 5, 'Sajikan dengan sambal bawang dan lalapan.'),
(25, 'cara memasak', 1, 'Rebus dada ayam hingga matang. Suwir-suwir. Sisihkan (air rebusan ayam digunakan untuk kuah kaldu).'),
(25, 'cara memasak', 2, 'Campur tepung plain dan air hingga menjadi adonan kental, beri garam secukupnya. Goreng hingga kecoklatan. Iris kotak-kotak. Sisihkan.'),
(25, 'cara memasak', 3, 'Tumis bawang putih hingga wangi. Masukkan irisan bakso ikan, ayam suwir, lada bubuk dan oyster sauce, aduk rata. Tambahkan kuah kaldu sesuai selera. Tunggu hingga mendidih.'),
(25, 'cara memasak', 4, 'Masukkan wortel, jamur dan tepung goreng. Tutup selama lima menit.'),
(25, 'cara memasak', 5, 'Masukkan pakcoy, daun bawang, dan garam secukupnya. Matikan kompor, koreksi rasa.'),
(25, 'cara memasak', 6, 'Sajikan dengan taburan bawang merah dan cabai goreng.'),
(26, 'cara memasak', 1, 'Rebus ceker ayam selama 10 menit, kemudian buang air rebusan.'),
(26, 'cara memasak', 2, 'Tumis bumbu halus hingga wangi, tambahkan sereh, lengkuas, daun jeruk, dan oyster sauce.'),
(26, 'cara memasak', 3, 'Masukkan ceker, kecap manis, dan garam. Aduk rata.'),
(26, 'cara memasak', 4, 'Tambahkan air. Masak ceker hingga empuk dan bumbu meresap. Koreksi rasa.'),
(26, 'cara memasak', 5, 'Sajikan dengan nasi hangat.'),
(27, 'cara memasak', 1, 'Ceplok telur. Sisihkan.'),
(27, 'cara memasak', 2, 'Tumis bumbu halus hingga wangi, tambahkan lada.'),
(27, 'cara memasak', 3, 'Masukkan telur ceplok dan garam. Aduk rata.'),
(27, 'cara memasak', 4, 'Tambahkan santan. Masak hingga mendidih. Koreksi rasa.'),
(27, 'cara memasak', 5, 'Sajikan dengan nasi hangat.'),
(28, 'cara memasak', 1, 'Telur dadar: Iris tipis bawang merah, bawang putih, cabai, dan daun bawang.'),
(28, 'cara memasak', 2, 'Dalam wadah, pecahkan telur, masukkan irisan bumbu, dan semua bahan. Kocok hingga berbuih.'),
(28, 'cara memasak', 3, 'Panaskan minyak. Goreng telur hingga kuning kecoklatan.'),
(28, 'cara memasak', 4, 'Sambal ijo: Didihkan air. Masukkan cabai, bawang merah, dan bawang putih. Rebus selama 5 menit. Tiriskan.'),
(28, 'cara memasak', 5, 'Haluskan cabai dan bawang yang sudah direbus, tambahkan garam dan lada. Koreksi rasa.'),
(28, 'cara memasak', 6, 'Sajikan telur dadar dan sambal ijo bersama nasi hangat dan lalapan timun dan kale rebus.'),
(29, 'cara memasak', 1, 'Iris pare (jangan terlalu tipis). Beri garam, remas-remas sebentar untuk mengurangi rasa pahit. Cuci.'),
(29, 'cara memasak', 2, 'Tumis bumbu iris hingga wangi. Masukkan pare dan air. Masak hingga pare agak layu dan air menyusut.'),
(29, 'cara memasak', 3, 'Masukkan teri goreng, gula, dan garam. Aduk rata. Koreksi rasa.'),
(29, 'cara memasak', 4, 'Sajikan dengan nasi hangat.'),
(30, 'cara memasak', 1, 'Rebus spaghetti hingga matang, tiriskan.'),
(30, 'cara memasak', 2, 'Tumis bawang putih hingga wangi. Masukkan ayam dan oyster sauce. Tumis hingga ayam matang.'),
(30, 'cara memasak', 3, 'Masukkan spaghetti, kecap manis, lada, daun bawang, dan garam. Aduk rata. Koreksi rasa.'),
(30, 'cara memasak', 4, 'Sajikan selagi hangat, beri taburan bawang merah goreng.'),
(31, 'cara memasak', 1, 'Tumis bumbu halus hingga wangi. Masukkan sereh, lengkuas, daun jeruk. Tumis hingga layu.'),
(31, 'cara memasak', 2, 'Masukkan chicken mince dan ceker. Tambahkan oyster sauce, kecap, garam, dan air. Masak hingga ayam dan ceker matang dan air menyusut.'),
(31, 'cara memasak', 3, 'Masukkan daun bawang.'),
(31, 'cara memasak', 4, 'Koreksi rasa.'),
(32, 'cara memasak', 1, 'Adonan A: Tuang santan ke dalam panci. Masukkan garam dan gula, aduk rata.'),
(32, 'cara memasak', 2, 'Di wadah lain, larutkan tepung terigu dengan santan yang sudah dicampur garam dan gula sekitar 10 sdm.'),
(32, 'cara memasak', 3, 'Saat tepung terigu sudah larut, tuang dan masukkan bersama ke dalam larutan santan dalam panci kemudian didihkan dengan api sedang cenderung kecil, sambil terus diaduk hingga adonan mengental.'),
(32, 'cara memasak', 4, 'Jika sudah mengental, matikan api kompor dan biarkan adonan dingin terlebih dahulu.'),
(32, 'cara memasak', 5, 'Adonan B: Tuang semua bahan B ke dalam panci, aduk rata dan didihkan dengan api kecil.'),
(32, 'cara memasak', 6, 'Aduk adonan hingga mengental dan tidak ada gerindil-gerindil tepung. Matikan api.'),
(32, 'cara memasak', 7, 'Adonan C: Siapkan wadah, masukkan telur dan gula lalu kocok hingga gula pasir larut.'),
(32, 'cara memasak', 8, 'Jika gula pasir sudah larut, masukkan santan kemudian aduk hingga rata.'),
(32, 'cara memasak', 9, 'Masukkan terigu (sebaiknya disaring) sedikit demi sedikit sambil terus diaduk agar terigu tidak menggerindil.'),
(32, 'cara memasak', 10, 'Tuang adonan B ke dalam adonan C lalu aduk sehingga kedua adonan tercampur rata.'),
(32, 'cara memasak', 11, 'Jika adonan B dan C sudah tercampur rata, saring kembali adonan untuk memastikan tidak ada terigu yang menggumpal.'),
(32, 'cara memasak', 12, 'Siapkan cetakan kue (bentuk mencembung), oleskan minyak sayur pada cetakan.'),
(32, 'cara memasak', 13, 'Adonan A masukkan ke dalam plastik piping bag.'),
(32, 'cara memasak', 14, 'Tuang adonan hijau sampai 3/4 cetakan. Lakukan sampai semua cetakan terisi adonan.'),
(32, 'cara memasak', 15, 'Semprotkan adonan A ke dalam masing-masing cetakan kue yang telah diisi adonan hijau.'),
(32, 'cara memasak', 16, 'Siapkan kukusan. Jika kukusan sudah panas, masukkan semua cetakan ke dalam kukusan dan kukus selama 20-25 menit.'),
(32, 'cara memasak', 17, 'Jika kue sudah matang, tunggu hingga kue agak dingin lalu keluarkan dari cetakan.'),
(33, 'cara memasak', 1, 'Bekukan semua buah-buahan ke dalam freezer, kecuali avocado.'),
(33, 'cara memasak', 2, 'Keluarkan semua buah-buahan beku.'),
(33, 'cara memasak', 3, 'Campurkan semua bahan ke dalam bowl besar.'),
(33, 'cara memasak', 4, 'Siram dengan susu terlebih dahulu, serta sedikit syrupnya.'),
(33, 'cara memasak', 5, 'Biarkan meleleh sendiri atau diaduk-aduk agar cepat mencair, atau boleh dipukul-pukul dengan sendok agar bisa menyerupai es crushed.'),
(33, 'cara memasak', 6, 'Siapkan fruit cocktail, (jika kalengan, air cocktailnya jangan diikutkan).'),
(33, 'cara memasak', 7, 'Potong dadu avocado.'),
(33, 'cara memasak', 8, 'Masukkan cocktail fruitnya serta alpukat potongannya, tambahkan syrup atau gula sesuai selera.'),
(33, 'cara memasak', 9, 'Sebelum disajikan, dapat ditambahkan satu sendok teh garam, atau sesuai selera.'),
(34, 'cara memasak', 1, 'Rebus air bersama gula, cengkeh dan kayu manis hingga mendidih.'),
(34, 'cara memasak', 2, 'Jika air sudah mendidih, matikan api, masukkan nanas. Tutup panci selama 10 menit.'),
(34, 'cara memasak', 3, 'Setelah agak dingin, pindahkan ke wadah. Kemudian tambahkan cocktail dan chia seed.'),
(34, 'cara memasak', 4, 'Siap disajikan.'),
(35, 'cara memasak', 1, 'Panggang pisang hingga kecoklatan.'),
(35, 'cara memasak', 2, 'Pipihkan roti tawar menggunakan rolling pan atau tekan-tekan menggunakan sendok makan.'),
(35, 'cara memasak', 3, 'Olesi roti tawar dengan Nutella, beri pisang, keju, kemudian gulung.'),
(35, 'cara memasak', 4, 'Panggang roti menggunakan butter hingga kecoklatan.'),
(35, 'cara memasak', 5, 'Taburi topping.'),
(36, 'cara memasak', 1, 'Tuang dan didihkan air bersama gula merah, asam, kecap dan sejumput garam.'),
(36, 'cara memasak', 2, 'Masak sampai mendidih dan semua bahan tercampur merata. Tunggu sampai air rebusan sedikit berkurang (reduced) dan kuah berwarna lebih gelap.'),
(36, 'cara memasak', 3, 'Diamkan kuah sampai dingin atau suhu ruangan.'),
(36, 'cara memasak', 4, 'Untuk toppingnya, gerus kasar bawang merah dan cabai sesuai selera, lalu sisihkan.'),
(36, 'cara memasak', 5, 'Siapkan mangkuk dan tahu yang sudah dipotong-potong sesuai selera.'),
(36, 'cara memasak', 6, 'Tambahkan gerusan cabai dan bawang diatas tahu.'),
(36, 'cara memasak', 7, 'Siram potongan tahu dengan kuah yang sudah dingin.'),
(37, 'cara memasak', 1, 'Campurkan soft cheese dan gula hingga lembut dengan mixer berkecepatan tinggi.'),
(37, 'cara memasak', 2, 'Tambahkan telur satu per satu, aduk kembali dengan mixer.'),
(37, 'cara memasak', 3, 'Tambahkan heavy cream, aduk rata dengan mixer.'),
(37, 'cara memasak', 4, 'Terakhir masukkan tepung terigu, campur hingga merata.'),
(37, 'cara memasak', 5, 'Alasi loyang dengan baking paper melebihi loyangnya, karena adonan akan mengembang tinggi.'),
(37, 'cara memasak', 6, 'Masukkan ke oven dengan suhu 200 derajat C selama 1 jam. Pada menit ke-50, jika sudah kecoklatan tunggu sekitar 5 menit lalu matikan oven, angkat.'),
(37, 'cara memasak', 7, 'Jika bagian tengah belum settle, tidak mengapa karena nanti saat dingin akan bagus bentuknya.'),
(38, 'cara memasak', 1, 'Panaskan oven api atas 180 dan api bawah 190 derajat Celcius atau 160 derajat Celcius untuk tipe standing oven.'),
(38, 'cara memasak', 2, 'Kocok telur gula sampai kental putih mengembang, turunkan kecepatan, masukkan pisang yang sudah dihaluskan, dan mixer lagi sebentar sampai rata.'),
(38, 'cara memasak', 3, 'Masukkan campuran terigu, kayu manis, soda kue, dan maizena, mixer dengan kecepatan rendah sampai tercampur rata.'),
(38, 'cara memasak', 4, 'Masukkan minyak sayur/lelehan butter, aduk balik dengan spatula.'),
(38, 'cara memasak', 5, 'Setelah benar-benar rata, tuang ke dalam loyang yang sudah dioles mentega dan ditaburi tepung.'),
(38, 'cara memasak', 6, 'Oven selama kurang lebih 45 menit (sampai matang), sesuaikan dengan oven masing-masing. Oven dipanaskan dulu 10-15 menit sebelum loyang masuk.'),
(39, 'cara memasak', 1, 'Peel and fry the banana with butter until golden brown (kupas dan goreng pisang dengan butter sampai kecoklatan).'),
(39, 'cara memasak', 2, 'Cut the banana into 3 cm long.'),
(39, 'cara memasak', 3, 'Cut the cheese into small bar (3 cm long).'),
(39, 'cara memasak', 4, 'Cut the puff pastry sheet into 12 rectangles.'),
(39, 'cara memasak', 5, 'Roll over the pastry sheet forwards and backwards until the small rectangle is about 12 cm x 10 cm.'),
(39, 'cara memasak', 6, 'Put the cheese, banana and one tsp of Nutella in the middle of small puff pastry sheet and wrap it properly.'),
(39, 'cara memasak', 7, 'Brush with beaten egg yolk.'),
(39, 'cara memasak', 8, 'Sprinkle with shredded cheese.'),
(39, 'cara memasak', 9, 'Bake at 200 degrees Celsius for 20-25 minutes (or until golden brown).'),
(40, 'cara memasak', 1, 'Cuci ubi manis sampai bersih kemudian rebus atau kukus sampai matang.'),
(40, 'cara memasak', 2, 'Angkat ubi manis dan buang kulitnya kemudian haluskan di dalam mangkuk.'),
(40, 'cara memasak', 3, 'Masukkan tepung ketan dan aduk merata hingga terbentuk menjadi adonan.'),
(40, 'cara memasak', 4, 'Bentuk adonan menjadi bola-bola kecil dan isi di dalamnya dengan gula merah.'),
(40, 'cara memasak', 5, 'Rebus adonan. Angkat ketika mengambang (matang).'),
(40, 'cara memasak', 6, 'Gulingkan ke kelapa parut.'),
(40, 'cara memasak', 7, 'Sajikan.'),
(41, 'cara memasak', 1, 'Untuk unti: Larutkan gula aren/merah dengan air matang atau santan di dalam panci diatas kompor dengan api sedang. Setelah larut, saring agar larutannya bersih.'),
(41, 'cara memasak', 2, 'Masukkan ke dalam panci yang berisi larutan gula di atas, gula pasir, garam dan daun pandan yang sudah disimpul. Masak hingga mendidih, kemudian masukkan kelapa parut. Dimasak dengan api sedang, sampai larutan gula tercampur dengan parutan kelapa, dan airnya menyusut.'),
(41, 'cara memasak', 3, 'Untuk kulit: Masukkan telur dalam wadah, kocok lepas, tambahkan santannya dan air matang. Aduk rata, masukkan gula pasir dan garamnya, diaduk kembali sampai rata berupa adonan cair.'),
(41, 'cara memasak', 4, 'Bagi menjadi 4 bagian, setiap bagian diberi warna masing-masing dengan pewarna makanan. Siapkan wajan non stick atau teflon, olesi dengan kuas sedikit minyak, dan buat dadar satu persatu untuk warna masing-masing.'),
(41, 'cara memasak', 5, 'Isikan unti kelapa disetiap kulit dadar, satu sendok makan atau satu sendok teh, sesuai dengan besarnya kulit dadar. Dilipat seperti bentuk amplop. Kemudian dihias dengan bentuk bunga atau bintang.'),
(42, 'cara memasak', 1, 'Pilih desicated coconut yang serutannya kasar, jangan pilih yang serutannya halus dan hancur, untuk mendapatkan hasil yang prima.'),
(42, 'cara memasak', 2, 'Desicated coconut dicampur rata dengan santan, dibiarkan terendam beberapa waktu.'),
(42, 'cara memasak', 3, 'Mentega dicairkan/microwave hingga cair, dimasukkan gula dan telur, kemudian dimixer hingga tercampur rata.'),
(42, 'cara memasak', 4, 'Masukkan tepung ketan bergantian dengan desicated coconut + santan pada adonan sebelumnya. Sedikit ditambahkan vanilli dan garam, mixer atau diaduk merata.'),
(42, 'cara memasak', 5, 'Siapkan loyang yang sudah dilapisi kertas roti terlebih dahulu.'),
(42, 'cara memasak', 6, 'Masukkan adonan kedalam loyang, dioven selama 45 menit dengan gas mark-4 atau 180 C.'),
(42, 'cara memasak', 7, 'Jika sudah setengah matang, olesi bagian atas wingko dengan kuning telur.'),
(42, 'cara memasak', 8, 'Panggang kembali hingga matang.'),
(43, 'cara memasak', 1, 'Aduk rata bumbu halus, daging cincang, telur, dan santan kental, sisihkan.'),
(43, 'cara memasak', 2, 'Kocok telur hingga lepas, tambahkan santan, garam, aduk rata. Buat dadar tipis-tipis garis tengah 18 cm.'),
(43, 'cara memasak', 3, 'Ambil selembar dadar, isi dengan adonan daging di tengah, lipat bentuk amplop, gulung. Lakukan hingga adonan habis, kukus hingga matang.'),
(43, 'cara memasak', 4, 'Panaskan sedikit minyak, goreng hingga kuning.'),
(44, 'cara memasak', 1, 'Mix the potatoes, melted butter, egg yolks, milk powder and flour, in the large bowl knead it together until it forms a nice dough, put aside.'),
(44, 'cara memasak', 2, 'Heat 2 tbsp oil, fry the onion and garlic until golden brown, add the minced chicken and cook for 5 minutes then add the grated carrot and chopped spring onion, cook it further until all are soft, add seasoning.'),
(44, 'cara memasak', 3, 'Take 2 tbsp of the dough shape it into a round, then put 1 tbsp of filling, fold and shape it into an oval sausage shape.'),
(44, 'cara memasak', 4, 'Dip it into slightly whisked egg white, then into the breadcrumbs and fry until golden brown.'),
(45, 'cara memasak', 1, 'Mixer kuning telur dengan gula sampai tercampur rata dan mengembang. Tambahkan garam, santan, kentang lembut, dan tepung terigu, diaduk menjadi adonan.'),
(45, 'cara memasak', 2, 'Panaskan loyang kue lumpur di atas kompor, dan loyang diberi olesan mentega/minyak. Masukkan adonan ke dalam loyang setinggi 3/4 tiap lubangnya, dan tutup.'),
(45, 'cara memasak', 3, 'Apabila sudah setengah matang masukkan nangka/raisinnya di atas tiap adonan. Dimasak sekitar 5 menit.'),
(45, 'cara memasak', 4, 'Apabila sudah kelihatan matang, angkat satu persatu, dan masukkan adonan berikutnya sampai habis.'),
(45, 'cara memasak', 5, 'Sajikan, dimakan setelah menunggu dingin sejenak.'),
(46, 'cara memasak', 1, 'Pembuatan bahan dasar/base: Didihkan air di dalam steamer/kukusan.'),
(46, 'cara memasak', 2, 'Campur ketan putih, santan, garam, dan selembar daun pandan dalam panci. Masak dan aduk sampai 3/4 matang (sampai santan meresap dalam ketan dan lembut).'),
(46, 'cara memasak', 3, 'Panaskan loyang yang telah diolesi minyak di dalam kukusan selama 5 menit.'),
(46, 'cara memasak', 4, 'Angkat loyang dan masukkan 3/4 ketan yang sudah setengah matang tadi, dan kukus selama 15 menit.'),
(46, 'cara memasak', 5, 'Pembuatan bahan atas/topping: Campurkan gula, santan, garam, daun pandan ke dalam panci dan masak sampai tercampur rata.'),
(46, 'cara memasak', 6, 'Jika sudah mendidih, sisihkan agar agak dingin.'),
(46, 'cara memasak', 7, 'Kocok telur dan tambahkan tepung terigu, aduk sampai tercampur rata.'),
(46, 'cara memasak', 8, 'Campur adonan telur dan tepung ini ke dalam adonan gula tadi, dan tambahkan pandan extract, kemudian dicampur rata (bisa menggunakan mixer).'),
(46, 'cara memasak', 9, 'Saring adonan tersebut agar tidak ada gumpalan.'),
(46, 'cara memasak', 10, 'Siramkan adonan topping pada adonan ketan yang di dalam kukusan.'),
(46, 'cara memasak', 11, 'Kukus kembali selama 20 menit.'),
(46, 'cara memasak', 12, 'Setelah matang, ambil dari kukusan dan diamkan sementara agar tidak terlalu panas.'),
(46, 'cara memasak', 13, 'Setelah dingin, potong-potong sesuai selera menggunakan pisau yang sudah diberi minyak sedikit.'),
(47, 'cara memasak', 1, 'Letakkan beras ketan di dalam kukusan, tambahkan santan dan garam. Kukus selama 30 menit.'),
(47, 'cara memasak', 2, 'Setelah matang, angkat dan pindahkan ke dalam loyang. Ratakan.'),
(47, 'cara memasak', 3, 'Kocok semua bahan A, tuangkan ke atas nasi ketan.'),
(47, 'cara memasak', 4, 'Kukus hingga masak, kurang lebih 30 menit.'),
(48, 'cara memasak', 1, 'Kukus singkong selama 30 menit atau sampai empuk.'),
(48, 'cara memasak', 2, 'Setelah matang, pindahkan singkong yang masih panas ke dalam baskom, tambahkan vanili.'),
(48, 'cara memasak', 3, 'Tumbuk singkong secara bertahap, sambil masukkan palm sugar, kelapa parut, dan gula pasir.'),
(48, 'cara memasak', 4, 'Cetak tumbukan singkong di loyang, padatkan.'),
(48, 'cara memasak', 5, 'Iris gethuk sesuai selera. Sajikan untuk teman minum teh atau kopi.'),
(49, 'cara memasak', 1, 'Unti kelapa: Rebus air, gula merah, daun pandan, garam, dan vanili. (Saring bila perlu untuk membersihkan ampas gula merah).'),
(49, 'cara memasak', 2, 'Masukkan kelapa parut, masak sambil diaduk sampai agak mengering. Dinginkan dan sisihkan.'),
(49, 'cara memasak', 3, 'Ketan hijau: Campur santan, pasta pandan, beras ketan, daun pandan, dan garam. Masak (sambil sesekali diaduk) dengan api sedang cenderung kecil sampai mengering.'),
(49, 'cara memasak', 4, 'Angkat dan kukus sekitar 30 menit.'),
(49, 'cara memasak', 5, 'Siapkan cetakan (bebas, bisa pakai cetakan talam). Masukkan satu sendok teh unti kelapa, tekan-tekan. Tambahkan ketan di atasnya hingga penuh, keluarkan dari cetakan, sajikan.'),
(50, 'cara memasak', 1, 'Sisir halus gula merah untuk isian klepon.'),
(50, 'cara memasak', 2, 'Siapkan wadah, campur tepung ketan, garam, dan pasta pandan secukupnya. Aduk rata.'),
(50, 'cara memasak', 3, 'Tambahkan air sedikit demi sedikit, uleni adonan tepung sampai kalis kemudian bentuk bulat-bulat.'),
(50, 'cara memasak', 4, 'Pipihkan adonan yang telah dibentuk bulat, beri isian gula merah kemudian bulatkan lagi.'),
(50, 'cara memasak', 5, 'Rebus air hingga mendidih kemudian masukkan bulatan klepon satu persatu, rebus klepon sampai matang (mengapung).'),
(50, 'cara memasak', 6, 'Angkat klepon yang telah matang, tiriskan kemudian gulingkan pada taburan kelapa.'),
(50, 'cara memasak', 7, 'Sajikan klepon untuk camilan bersama teh hangat atau kopi panas.'),
(51, 'cara memasak', 1, 'Tumis bawang bombay hingga layu. Masukkan daging, aduk rata.'),
(51, 'cara memasak', 2, 'Tambahkan garlic powder, ketumbar, jintan, dan garam. Aduk rata kembali hingga daging matang. Sisihkan.'),
(51, 'cara memasak', 3, 'Kocok telur di wadah baskom. Tambahkan daun bawang dan daging. Aduk rata.'),
(51, 'cara memasak', 4, 'Ambil satu lembar kulit spring roll. Beri 3 sendok makan adonan telur, lipat seperti amplop.'),
(51, 'cara memasak', 5, 'Goreng martabak di minyak panas hingga kuning kecoklatan. Tiriskan.'),
(51, 'cara memasak', 6, 'Sajikan dengan acar timun/pickles.'),
(52, 'cara memasak', 1, 'Kupas semua buah-buahan dan ketela pohon/sweet potatoes kemudian diparut (kecuali nanas). Nanas dipotong kecil seperti korek api.'),
(52, 'cara memasak', 2, 'Rebus 250 gr gula merah/jawa dengan air secukupnya sampai mencair.'),
(52, 'cara memasak', 3, 'Haluskan cabai dan terasi, kemudian tambahkan air asam.'),
(52, 'cara memasak', 4, 'Siapkan wadah, masukkan rebusan air gula, bumbu halus dan buah buahan. Aduk hingga tercampur.'),
(52, 'cara memasak', 5, 'Masukkan ke dalam lemari es sekitar satu jam dan sajikan setelah dingin.');
INSERT INTO `resep_catatan` (`resep_id`, `jenis`, `teks`) VALUES
(8, 'tips', 'Untuk rasa yang lebih enak, bisa juga spaghetti ditumis bersama dengan dendeng balado.'),
(9, 'cara_penyajian', 'Tuang di atas piring saji taburi dengan irisan tipis cabe merah besar (buang biji nya) dan bawang goreng. Masakan ini bisa langsung dimakan dengan nasi putih atau bersamaan dengan opor ayam.'),
(10, 'cara_penyajian', 'Goreng ungkep ayam/daging/hati ayam sebelum dimakan, sajikan dengan sambal ala Indonesia dan nasi panas.'),
(10, 'cara_penyimpanan', 'Untuk di frozen bungkus per porsi di dalam plastik ziplock, setiap saat ingin mengkonsumsi tinggal digoreng.'),
(11, 'tips', 'Jika ingin tekstur gudeg agak basah, boleh hanya memasak 4 jam saja. Jika ingin telur gudeg berwarna coklat gelap, masukkan telur rebus sekalian bersama memasak nangka. Untuk ayam, tahu, dan tempe berwarna coklat gelap, dapat sekalian dimasukkan bersama nangkanya.'),
(19, 'cara_menghidangkan', 'Tata sayuran rebus dalam piring lalu tuangi saus secukupnya. Paling nikmat dimakan bersama kerupuk dan tempe gembus bacem.'),
(20, 'catatan', 'Mustard Green adalah sejenis sawi yang bisa didapatkan di toko Cina, kadang disebut European Kai Choi. Nama lain: Gai Choi, Siu Gai Choi, Xaio Jie Cai, Baby Mustard, Chinese Leaf Mustard, Indian Mustard, Mostaza, dan Mustard Greens.'),
(25, 'catatan', 'Jenis sayuran bisa disesuaikan selera. Protein bisa diganti dengan seafood (udang, cumi, kerang, ikan fillet).'),
(26, 'catatan', 'Ceker ayam/chicken feet/chicken paws tersedia di toko Asia dan beberapa toko daging halal dalam kemasan 1 kg frozen. Cabai rawit merah yang paling mudah ditemukan adalah red bird''s eye chili/red Thai chili.'),
(27, 'catatan', 'Shallot dapat diganti dengan red onion yang lebih mudah didapat dan harganya relatif lebih murah.'),
(29, 'catatan', 'Pare dapat ditemukan dalam bentuk utuh segar maupun kemasan frozen. Ada beberapa jenis pare yang biasa dijual di toko Asia maupun muslim fresh grocery, diantaranya Karela (India) dan Chinese Bitter Melon.'),
(30, 'catatan', 'Untuk mematangkan ayam, tidak perlu ditambah air karena ayam akan mengeluarkan minyak. Ayam dapat diganti dengan seafood atau daging sapi, sesuai selera.'),
(31, 'cara_penyajian', 'Tata mie shanghai di mangkuk. Siram dengan ayam dan kuahnya. Lengkapi dengan pakcoy rebus, ceker, bakso, pangsit, dan taburan daun bawang.'),
(31, 'catatan', 'Chicken mince dapat diganti dengan dada ayam yang direbus kemudian dipotong dadu.'),
(33, 'tips', 'Diusahakan tidak memakai buah nanas agar asamnya tidak merusak rasa. Untuk nanas, jangan dibekukan, biarkan segar, dapat dipotong pada saat terakhir saja sebelum es teler disajikan.'),
(34, 'catatan', 'Simpan di kulkas dan sajikan esok hari untuk rasa yang lebih mantap.'),
(35, 'catatan', 'Sajian untuk 4 porsi.'),
(42, 'catatan', 'Untuk satu resep dengan loyang ukuran 28x24 cm.'),
(46, 'catatan', 'Daun pandan, ketan putih, bisa dibeli di oriental stores.'),
(47, 'catatan', 'Karena tidak punya kukusan yang besar, bisa dipanggang di oven 150C selama 45 menit dengan teknik rendaman panggang (loyang berisi adonan direndam di dalam loyang yang lebih besar berisi air, air rendaman harus dijaga agar tidak habis).'),
(48, 'catatan', 'Cassava/singkong dapat dibeli di toko Asia dalam bentuk singkong segar atau singkong kupas frozen. Gethuk bisa juga digoreng (celupkan dalam adonan tepung plain dengan konsistensi kental, kemudian goreng di minyak panas hingga kecoklatan).');
