SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `langkah`;
DROP TABLE IF EXISTS `bahan`;
DROP TABLE IF EXISTS `resep_catatan`;
DROP TABLE IF EXISTS `resep`;

CREATE TABLE `resep` (
  `id` INT UNSIGNED NOT NULL,
  `nama` VARCHAR(150) NOT NULL,
  `kategori` VARCHAR(50) NOT NULL,
  `kontributor` VARCHAR(150) DEFAULT NULL,
  `kota` VARCHAR(100) DEFAULT NULL,
  `halaman` VARCHAR(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `bahan` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `resep_id` INT UNSIGNED NOT NULL,
  `grup` VARCHAR(150) NOT NULL COMMENT 'nama kelompok bahan, misal: Bahan, Bumbu Halus, Bahan A - dst',
  `urutan` INT UNSIGNED NOT NULL,
  `teks` VARCHAR(500) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_bahan_resep` (`resep_id`),
  CONSTRAINT `fk_bahan_resep` FOREIGN KEY (`resep_id`) REFERENCES `resep` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `langkah` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `resep_id` INT UNSIGNED NOT NULL,
  `grup` VARCHAR(150) NOT NULL COMMENT 'nama sub-resep/tahap, misal: Cara Memasak, Sambal Krecek - Cara Memasak',
  `urutan` INT UNSIGNED NOT NULL,
  `instruksi` TEXT NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_langkah_resep` (`resep_id`),
  CONSTRAINT `fk_langkah_resep` FOREIGN KEY (`resep_id`) REFERENCES `resep` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `resep_catatan` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `resep_id` INT UNSIGNED NOT NULL,
  `jenis` VARCHAR(50) NOT NULL COMMENT 'tips, catatan, cara_penyajian, cara_penyimpanan, dsb',
  `teks` TEXT NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_catatan_resep` (`resep_id`),
  CONSTRAINT `fk_catatan_resep` FOREIGN KEY (`resep_id`) REFERENCES `resep` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

